// Demo state belongs to a campaign; switching campaigns never changes its siblings.
const workflowFields=['lang','size','scope','version','save','overrides','translations','approved','requested','history','reviewed','human','color','font','focus','asset','selection','download'];
function snapshot(){return Object.fromEntries(workflowFields.map(k=>[k,structuredClone(state[k])]))}
function initialWorkflow(c){const approved={},reviewed={0:true};const ids=c.languageIds||Array.from({length:c.langs},(_,i)=>i);const ss=c.sizeIds||Array.from({length:c.sizes},(_,i)=>i);if(c.status==='승인 완료')for(const l of ids){reviewed[l]=true;for(const s of ss)approved[l+'-'+s]=1}return {lang:ids[0],size:ss[0],scope:'common',version:1,save:'모든 변경사항 저장됨',overrides:{},translations:{},approved,requested:c.status==='검수 대기',history:[],reviewed,human:{},color:'#dcedff',font:31,focus:50,asset:null,selection:[],download:'idle'}}
camp().workflow=snapshot();
function openCampaign(c){camp().workflow=snapshot();state.campaign=campaigns.indexOf(c);Object.assign(state,c.workflow||initialWorkflow(c));navigate('edit')}
const baseStatus=status;
status=function(l,s){const o=state.overrides[l+'-'+s];const title=o?.title||state.translations[l]?.title||(l===0?camp().data.title:'');const short=o?.short||state.translations[l]?.short;if((title.length>(s===1?40:85))&&!(s===1&&short&&short.length<=32))return '글자 넘침';return baseStatus(l,s)};
const baseSave=saveChange;
saveChange=function(k,v){const local=state.scope==='local'&&!['amount','coupon','period'].includes(k);const approvals={...state.approved};baseSave(k,v);if(local){for(const id of Object.keys(approvals))if(id!==key())state.approved[id]=state.version;}state.requested=false;state.download='idle';if(!state.history[0]?.startsWith('내용 변경'))state.history.unshift(`내용 변경 · ${local?langs[state.lang]+' / '+sizes[state.size].name:'공통 데이터'} · 재검수 필요`);if($('#liveIssue'))$('#liveIssue').textContent=status(state.lang,state.size)==='글자 넘침'?'! 글자 넘침 · 수정 필요':'✓ 텍스트 길이 적절함';};
const baseRender=render;
render=function(){baseRender();if(state.page==='edit'){
 const check=$('.checks .check:nth-child(2) strong');if(check){check.id='liveIssue';check.textContent=status(state.lang,state.size)==='글자 넘침'?'! 글자 넘침 · 수정 필요':'텍스트 길이 적절함'}
 if(state.lang!==0){const call=document.createElement('div');call.className='callout';call.style='margin-bottom:15px;font-size:12px';call.innerHTML=`${langs[state.lang]} 결과물을 보고 있어요.<br>공통 입력은 한국어 원문입니다. <button class="small" id="goTranslate">번역 편집 →</button>`;$('.panel').insertBefore(call,$('.scope'));$('#goTranslate').onclick=()=>navigate('languages')}
 if(state.scope==='local')for(const name of ['amount','coupon','period']){const el=$(`[data-field="${name}"]`);if(el){el.disabled=true;el.parentElement.insertAdjacentHTML('beforeend','<span class="hint">♧ 공통 데이터 · 공통 내용에서 변경</span>')}}
 $('#toggleChecks').onclick=()=>{if(window.innerWidth<=1200){$('.editor').classList.toggle('showchecks')}else{state.hide=!state.hide;render()}};const priorFail=$('#saveFail').onclick;$('#saveFail').onclick=()=>{priorFail();const retry=document.createElement('button');retry.className='small';retry.textContent='저장 다시 시도';retry.id='retrySave';retry.onclick=()=>{state.save='저장 중…';render();setTimeout(()=>{state.save='모든 변경사항 저장됨';render();notify('데모 저장을 다시 시도했어요.')},600)};$('#saveFail').after(retry)};
 for(const id of ['font','focus']){const el=$('#'+id),old=el.oninput;el.oninput=e=>{old(e);delete state.approved[key()];state.history.unshift('디자인 개별 수정 · '+langs[state.lang]+' / '+sizes[state.size].name);state.download='idle'}}
 $$('[data-color]').forEach(el=>{const old=el.onclick;el.onclick=()=>{delete state.approved[key()];state.download='idle';old()}});
 const designer=$('#designer').onclick;$('#designer').onclick=()=>{designer();if(state.role==='디자이너'&&$('#layout')){const old=$('#layout').onchange;$('#layout').onchange=e=>{delete state.approved[key()];old(e)}}};
 }
 $$('[data-campaign]').forEach(b=>{b.onclick=()=>openCampaign(campaigns[+b.dataset.campaign]);b.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();b.onclick()}}});
 $$('[data-duplicate]').forEach(b=>b.onclick=()=>{camp().workflow=snapshot();const c=campaigns[+b.dataset.duplicate];const copied={...c,name:c.name+' (복사)',status:'작업 중',data:{...c.data},workflow:null};const current=camp();campaigns.push(copied);state.campaign=campaigns.indexOf(current);render();notify('캠페인을 복제했어요. 목록 아래에서 이어서 편집하세요.')});
 if($('#create'))$('#create').onclick=()=>{const n=$('#newName').value.trim(),date=$('#newDate').value;if(!n||!date||!state.newLangs.length||!state.newSizes.length)return notify('캠페인명, 마감일, 언어와 규격을 입력해 주세요.');const c={name:n,owner:$('#newOwner').value,date,status:'작업 중',langs:state.newLangs.length,sizes:state.newSizes.length,languageIds:[...state.newLangs],sizeIds:[...state.newSizes],data:{...defaults,title:state.template===0?defaults.title:tnames[state.template],amount:[2,3,4].includes(state.template)?'':defaults.amount}};campaigns.push(c);openCampaign(c);notify('캠페인을 생성했어요. 선택한 언어와 규격에만 결과물이 연결돼요.')};
 if(state.page==='languages'){$$('[data-translate]').forEach(e=>{const old=e.oninput;e.oninput=()=>{const previous=state.version;old();state.version++;for(const k of Object.keys(state.approved))if(state.approved[k]===previous)state.approved[k]=state.version;state.requested=false;state.download='idle';camp().status='수정 필요'}});const b=$('#approveLanguage');if(state.role!=='언어 검수자')b.textContent='번역 검수 완료 · 검수자 전용';else b.textContent=state.reviewed[state.lang]?'✓ 번역 검수 완료됨':'번역 검수 완료';const old=b.onclick;b.onclick=()=>{old();if(state.reviewed[state.lang])state.history.unshift(langs[state.lang]+' 번역 검수 완료')};if(state.lang===0){$$('[data-translate]').forEach(e=>e.disabled=true);b.disabled=true;b.textContent='한국어 원문 · 내용 편집에서 수정'} }
 if(state.page==='download'){
 const baseApprove=$('#approveFinal').onclick;$('#approveFinal').onclick=()=>{if(!state.requested){notify('먼저 현재 버전의 검수를 요청해 주세요.');return}baseApprove()};
 const baseRequest=$('#requestReview').onclick;$('#requestReview').onclick=baseRequest;
 if(camp().name!=='버스 할인 쿠폰 이벤트'){$$('.timeline p').slice(-3).forEach(p=>p.remove());$('.timeline').insertAdjacentHTML('beforeend','<p>캠페인 생성 · 승인 템플릿 v2.1<small>데모 세션</small></p>')}if(state.output==='selected')$('.chips').style='max-height:180px;overflow:auto';
 if(state.output==='approved'){$('.filename').textContent=camp().name.replaceAll(' ','_')+'_approved_v'+state.version+'.zip';$('.filename').insertAdjacentHTML('afterend',`<p class="footnote">ZIP 내부 예: ${esc(camp().name.replaceAll(' ','_'))}_ko_800x840_v${state.version}.${state.format.toLowerCase()}</p>`)}
 if(state.format==='PNG')$('#exportBg').parentElement.insertAdjacentHTML('beforeend','<label class="hint"><input type="checkbox" id="keepTransparent" checked> 투명 영역 유지</label>');
 if($('#keepTransparent')){$('#exportBg').disabled=true;$('#keepTransparent').onchange=e=>$('#exportBg').disabled=e.target.checked}
 }
 if(state.page==='templates'){if(camp().templateVersion)$('.card h2').textContent=tnames[state.template]+' · '+camp().templateVersion+' 초안';const baseNew=$('#newTemplate').onclick;$('#newTemplate').onclick=()=>{if(state.role!=='디자이너')return baseNew();confirmBox('템플릿 v2.2 초안을 만들까요?','v2.1로 만든 기존 승인 결과물은 유지됩니다.',()=>{camp().templateVersion='v2.2';render();notify('새 버전 v2.2 초안이 생성됐어요.')},'새 버전 생성')}}
 if(state.page==='settings'&&state.settingsTab==='운영 언어'){$('#addLanguage').onclick=()=>permission('디자이너',()=>{const name=$('#newLanguage').value.trim();if(!name)return notify('언어명을 입력해 주세요.');if(langs.includes(name))return notify('이미 등록된 언어예요.');langs.push(name);codes.push('sample'+langs.length);render();notify('언어를 등록했어요. 기존 캠페인에는 추가되지 않아요.')});}
 if(state.page==='assets'){$('#assetBrand').value=state.brand;$('#assetBrand').onchange=e=>{state.brand=e.target.value;render()};}
 if(state.page==='inbox')$$('[data-result]').forEach(b=>b.onclick=()=>{const id=b.dataset.result;openCampaign(campaigns.find(c=>c.name==='버스 할인 쿠폰 이벤트'));[state.lang,state.size]=id.split('-').map(Number);navigate(id==='0-0'?'download':'edit')});
};render();
